package com.yihe.framework.ehr;
import java.util.*;
import org.springframework.jdbc.datasource.*;
import org.springframework.transaction.support.TransactionTemplate;
import static com.yihe.framework.ehr.EhrAccess.*;
import static com.yihe.framework.ehr.EhrService.*;
public class OccupationalArchiveChecks {
 static void check(String label,boolean ok){if(!ok)throw new AssertionError(label);System.out.println("PASS "+label);}
 static void reject(String label,int code,Runnable action){try{action.run();throw new AssertionError(label);}catch(EhrException e){check(label,e.status==code);}}
 static Map<String,Object> request(OccupationalArchiveService s,EhrActor a,String record,String action){Map<String,Object> d=s.detail(a,record,null);return map("action",action,"requestKey",id(),"note","隔离测试依据：已核对原件和身份","expectedRevision",d.get("currentVersion"),"sourceDigest",d.get("sourceDigest"));}
 @SuppressWarnings("unchecked") public static void main(String[] args){if(!System.getenv("EHR_JDBC_URL").contains("/shayu_3_preview?"))throw new IllegalArgumentException("preview only");DriverManagerDataSource source=new DriverManagerDataSource(System.getenv("EHR_JDBC_URL"),System.getenv("EHR_DB_USER"),System.getenv("EHR_DB_PASSWORD"));EhrRepository db=new EhrRepository(source);EhrService ehr=new EhrService(db);EmployeeHealthArchiveService employees=new EmployeeHealthArchiveService(db,ehr);OccupationalArchiveService service=new OccupationalArchiveService(db,ehr,employees);String org="OCC_"+id().substring(0,8);EhrActor actor=new EhrActor("occupational-test",org,"synthetic",true,false),reader=new EhrActor("reader",org,"synthetic",false,false),other=new EhrActor("other",org+"X","synthetic",true,false),mode=new EhrActor("mode",org,"real",true,false),mobile=new EhrActor("mobile",org,"synthetic",false,true);
 new TransactionTemplate(new DataSourceTransactionManager(source)).execute(tx->{try{
 OcrRosterIdentityChecks.Fixture f=ArchiveReviewChecks.fixture(db,ehr,actor,true);ArchiveReviewService reviews=new ArchiveReviewService(db,ehr,new ReportMatchingService(db,ehr));reviews.act(actor,f.report,1,ArchiveReviewChecks.request(ehr,actor,f.report,"approve"));String roster=ehr.encode(ehr.profile(actor,f.record,false)),report=ehr.encode(ehr.snapshot(f.report,1));
 Map<String,Object> fresh=service.detail(actor,f.record,null);check("read_does_not_auto_create_archive",num(fresh.get("version"))==0&&"unfiled".equals(fresh.get("status")));
 reject("cross_unit_denied",404,()->service.detail(other,f.record,null));reject("cross_mode_denied",404,()->service.detail(mode,f.record,null));reject("mobile_denied",403,()->service.detail(mobile,f.record,null));
 Map<String,Object> save=request(service,actor,f.record,"save"),document=service.empty();document.put("surveillanceCategory","在岗检查（隔离测试）");document.put("hireDate","2020-01-01");save.put("document",document);
 reject("reader_write_denied",403,()->service.act(reader,f.record,save));Map<String,Object> saved=service.act(actor,f.record,save);check("save_creates_version_one",num(saved.get("version"))==1&&"draft".equals(saved.get("status")));service.act(actor,f.record,save);check("save_retry_idempotent",num(service.detail(actor,f.record,null).get("currentVersion"))==1);
 Map<String,Object> changed=new LinkedHashMap<>(save);changed.put("note","不同内容");reject("key_reuse_for_changed_body_denied",409,()->service.act(actor,f.record,changed));Map<String,Object> stale=new LinkedHashMap<>(save);stale.put("requestKey",id());reject("stale_revision_denied",409,()->service.act(actor,f.record,stale));
 Map<String,Object> bad=request(service,actor,f.record,"save"),badDoc=service.empty();badDoc.put("diagnoses",Arrays.asList(map("diagnosis","没有来源","sourceId",id())));bad.put("document",badDoc);reject("unrelated_clinical_source_denied",422,()->service.act(actor,f.record,bad));
 Map<String,Object> review=request(service,actor,f.record,"review");review.put("identityVerified",true);review.put("contentVerified",true);final Map<String,Object> earlyReview=review;reject("review_requires_employee_evidence_first",422,()->service.act(actor,f.record,earlyReview));
 Map<String,Object> confirm=request(service,actor,f.record,"confirm");confirm.put("sourceId",f.source);confirm.put("evidenceVerified",false);reject("confirmation_checkbox_required",422,()->service.act(actor,f.record,confirm));confirm.put("evidenceVerified",true);Map<String,Object> confirmed=service.act(actor,f.record,confirm);check("confirmation_is_new_evidence_version",num(confirmed.get("version"))==2&&"employee_confirmed".equals(confirmed.get("status"))&&f.source.equals(confirmed.get("confirmationSourceId")));
 review=request(service,actor,f.record,"review");final Map<String,Object> unsigned=review;reject("doctor_requires_explicit_original_checks",422,()->service.act(actor,f.record,unsigned));review.put("identityVerified",true);review.put("contentVerified",true);ehr.candidateOnly=true;final Map<String,Object> verified=review;reject("candidate_only_review_blocked",403,()->service.act(actor,f.record,verified));ehr.candidateOnly=false;
 Map<String,Object> reviewed=service.act(actor,f.record,review);check("doctor_review_creates_version_three",num(reviewed.get("version"))==3&&"reviewed".equals(reviewed.get("status")));check("does_not_publish_source_reports",db.count("SELECT COUNT(*) FROM a_report_publications WHERE report_id=?",f.report)==0);check("source_roster_preserved",roster.equals(ehr.encode(ehr.profile(actor,f.record,false))));check("source_report_preserved",report.equals(ehr.encode(ehr.snapshot(f.report,1))));check("historical_draft_retained","draft".equals(service.detail(actor,f.record,1).get("status")));
 Map<String,Object> next=request(service,actor,f.record,"save");Map<String,Object> changedDoc=new LinkedHashMap<>(document);changedDoc.put("protection","来自测试原件的防护记录");next.put("document",changedDoc);service.act(actor,f.record,next);check("editing_reviewed_document_resets_confirmation","draft".equals(service.detail(actor,f.record,null).get("status")));
 Map<String,Object> beforeUpdate=service.detail(actor,f.record,1),staleSource=request(service,actor,f.record,"save");staleSource.put("document",document);ehr.revise(actor,f.report,1,"隔离测试：按原流程建立报告修订版本");reject("changed_original_source_blocks_stale_save",409,()->service.act(actor,f.record,staleSource));Map<String,Object> afterUpdate=service.detail(actor,f.record,null);check("source_change_visible",Boolean.TRUE.equals(afterUpdate.get("sourceChanged")));check("historical_source_snapshot_immutable",ehr.encode(beforeUpdate.get("employee")).equals(ehr.encode(service.detail(actor,f.record,1).get("employee"))));
 OcrRosterIdentityChecks.Fixture unreviewed=ArchiveReviewChecks.fixture(db,ehr,actor,true);Map<String,Object> s2=request(service,actor,unreviewed.record,"save");s2.put("document",document);service.act(actor,unreviewed.record,s2);Map<String,Object> c2=request(service,actor,unreviewed.record,"confirm");c2.put("evidenceVerified",true);c2.put("sourceId",unreviewed.source);service.act(actor,unreviewed.record,c2);Map<String,Object> r2=request(service,actor,unreviewed.record,"review");r2.put("identityVerified",true);r2.put("contentVerified",true);reject("unreviewed_original_reports_block_doctor_review",422,()->service.act(actor,unreviewed.record,r2));
 check("audit_trail_saved",db.count("SELECT COUNT(*) FROM a_health_archive_audit_logs WHERE record_id=? AND action LIKE 'occupational_archive_%'",f.record)==4);
 }finally{tx.setRollbackOnly();}return null;});}
}
